PARENT = {'opl': 'oplossingen', 'sec': 'sectoren', 'pro': 'producten'}
KB = {
 'kb-filtratie': dict(old='/oil-filtration-systems/', sec='opl', slug=('industriele-oliefiltratie', 'industrial-oil-filtration', 'filtration-huile-industrielle'),
  nl=('Industriële oliefiltratie', 'Industriële oliefiltratie en filtersystemen – Triple R', 'Industriële oliefiltratie met bypassfilters: Triple R reinigt hydraulische olie en smeerolie, verlengt de olielevensduur en beperkt stilstand.',
      'Industriële oliefiltratie houdt hydraulische olie, smeerolie en motorolie schoon terwijl machines draaien. Triple R doet dat met bypassfilters: een kleine deelstroom gaat traag door een 114 mm dieptefilter dat deeltjes, varnish en water verwijdert. Zo gaat de olie jaren langer mee en dalen stilstand en onderhoudskosten.'),
  en=('Industrial oil filtration', 'Industrial oil filtration systems – Triple R', 'Industrial oil filtration with bypass filters: Triple R cleans hydraulic and lubricating oil, extends oil life and reduces downtime.',
      'Industrial oil filtration keeps hydraulic, lubricating and engine oil clean while machines run. Triple R does this with bypass filters: a small partial flow passes slowly through a 114 mm depth filter that removes particles, varnish and water. Oil lasts years longer, while downtime and maintenance costs fall.'),
  fr=('Filtration d\'huile industrielle', 'Filtration d\'huile industrielle et systèmes – Triple R', 'Filtration d\'huile industrielle par filtres en dérivation : Triple R nettoie les huiles hydrauliques et de lubrification et réduit les arrêts.',
      'La filtration d\'huile industrielle garde les huiles hydrauliques, de lubrification et moteur propres pendant que les machines tournent. Triple R utilise des filtres en dérivation : un petit débit partiel traverse lentement un filtre en profondeur de 114 mm qui élimine particules, vernis et eau. L\'huile dure des années de plus.')),
 'kb-varnish': dict(old='/tribology/varnish/', sec='opl', slug=('varnish-verwijderen', 'varnish-removal', 'elimination-des-vernis'),
  nl=('Varnish verwijderen uit hydraulische olie', 'Varnish verwijderen uit hydraulische olie – Triple R', 'Varnish en sludge doen kleppen haperen en filters verstoppen. Zo verwijdert u oxidatieresten met een 114 mm dieptefilter. Laat uw olie testen.',
      'Varnish is een dunne, onoplosbare film van oxidatieresten die zich afzet in hydraulische en smeersystemen. Het doet kleppen haperen, verstopt filters en verhoogt de wrijving. Een Triple R-filterelement van 114 mm houdt varnish en sludge vast; het V-element filtert daarvoor tot 1 µm absoluut.'),
  en=('Removing varnish from hydraulic oil', 'Varnish removal from hydraulic oil – Triple R', 'Varnish and sludge make valves stick and block filters. See how a 114 mm depth filter removes oxidation residues. Have your oil tested.',
      'Varnish is a thin, insoluble film of oxidation residues that deposits inside hydraulic and lubrication systems. It makes valves stick, blocks filters and increases friction. A 114 mm Triple R filter element retains varnish and sludge; the V element filters down to 1 µm absolute for this purpose.'),
  fr=('Éliminer les vernis de l\'huile hydraulique', 'Éliminer les vernis de l\'huile hydraulique – Triple R', 'Vernis et boues grippent les vannes et colmatent les filtres. Voyez comment un filtre en profondeur de 114 mm les élimine. Faites tester votre huile.',
      'Le vernis est un film mince et insoluble de résidus d\'oxydation qui se dépose dans les systèmes hydrauliques et de lubrification. Il grippe les vannes, colmate les filtres et augmente le frottement. Un élément filtrant Triple R de 114 mm retient vernis et boues ; l\'élément V filtre jusqu\'à 1 µm absolu.')),
 'kb-water': dict(old='/tribology/water/', sec='opl', slug=('water-in-olie', 'water-in-oil', 'eau-dans-l-huile'),
  nl=('Water in olie verwijderen', 'Water in olie verwijderen: oorzaken en oplossing – Triple R', 'Water versnelt oxidatie en corrosie in hydraulische olie. Ontdek hoe u olie ontwatert tot onder 100 ppm met filterelementen of een vacuümdroger.',
      'Water in olie versnelt oxidatie en corrosie en verkort de levensduur van machines. Een Triple R-filterelement absorbeert vrij en geëmulgeerd water tot onder 100 ppm. Bij veel water verwijdert de vacuümdroger 80% van het opgeloste en 100% van het vrije water, en scheidt de WS-serie continu water af.'),
  en=('Removing water from oil', 'Water in oil: causes and removal – Triple R', 'Water speeds up oxidation and corrosion in hydraulic oil. See how to dewater oil to below 100 ppm with filter elements or a vacuum dehydrator.',
      'Water in oil speeds up oxidation and corrosion and shortens machine life. A Triple R filter element absorbs free and emulsified water to below 100 ppm. With larger quantities, the vacuum dehydrator removes 80% of dissolved and 100% of free water, and the WS series separates water continuously.'),
  fr=('Éliminer l\'eau de l\'huile', 'L\'eau dans l\'huile : causes et solutions – Triple R', 'L\'eau accélère l\'oxydation et la corrosion de l\'huile hydraulique. Voyez comment la déshydrater sous 100 ppm avec éléments filtrants ou déshydrateur.',
      'L\'eau dans l\'huile accélère l\'oxydation et la corrosion et réduit la durée de vie des machines. Un élément filtrant Triple R absorbe l\'eau libre et émulsionnée jusqu\'à moins de 100 ppm. En grande quantité, le déshydrateur sous vide élimine 80 % de l\'eau dissoute et 100 % de l\'eau libre.')),
 'kb-deeltjes': dict(old='/tribology/solid-particles/', sec='opl', slug=('vaste-deeltjes', 'solid-particles', 'particules-solides'),
  nl=('Vaste deeltjes uit olie filtreren', 'Vuile hydraulische olie filtreren (ISO 4406) – Triple R', 'Fijne deeltjes onder 5 µm slijten pompen en servokleppen. Breng uw olie naar de juiste ISO 4406-reinheidsklasse met Triple R. Vraag een gratis analyse.',
      'Vaste deeltjes zoals slijtagemetaal, stof en silica slijpen pompen, kleppen en cilinders. De meeste schadelijke deeltjes zijn kleiner dan 5 µm en dus onzichtbaar. Triple R-dieptefilters halen ze uit de olie, met een fijnheid van 1 tot 10 µm absoluut, en brengen uw olie naar de juiste ISO 4406-reinheidsklasse.'),
  en=('Filtering solid particles from oil', 'Filtering dirty hydraulic oil (ISO 4406) – Triple R', 'Fine particles below 5 µm wear out pumps and servo valves. Bring your oil to the right ISO 4406 cleanliness class with Triple R.',
      'Solid particles such as wear metal, dust and silica grind down pumps, valves and cylinders. Most harmful particles are smaller than 5 µm and therefore invisible. Triple R depth filters remove them from the oil, with a fineness of 1 to 10 µm absolute, and bring your oil to the right ISO 4406 cleanliness class.'),
  fr=('Filtrer les particules solides de l\'huile', 'Filtrer l\'huile hydraulique sale (ISO 4406) – Triple R', 'Les particules fines de moins de 5 µm usent pompes et servovalves. Amenez votre huile à la bonne classe de propreté ISO 4406 avec Triple R.',
      'Les particules solides comme les métaux d\'usure, la poussière et la silice attaquent pompes, vannes et vérins. La plupart des particules nocives font moins de 5 µm et sont invisibles. Les filtres en profondeur Triple R les éliminent, avec une finesse de 1 à 10 µm absolus, et amènent votre huile à la bonne classe ISO 4406.')),
 'kb-lucht': dict(old='/tribology/air-bubbles/', sec='opl', slug=('lucht-en-schuim', 'air-and-foam', 'air-et-mousse'),
  nl=('Lucht en schuim in olie verwijderen', 'Lucht en schuim in hydraulische olie verwijderen – Triple R', 'Luchtbellen veroorzaken cavitatie, lawaai en snellere oxidatie. De Quicktoron verwijdert tot 95% van de lucht uit uw olie. Ontdek hoe.',
      'Lucht en schuim in olie veroorzaken cavitatie, lawaai en snellere oxidatie. Luchtbellen beschadigen pompen en maken hydraulische systemen minder nauwkeurig. De Quicktoron van Triple R is een cycloon-ontluchter die tot 95% van de luchtbellen uit de olie haalt en die los van het filterelement werkt.'),
  en=('Removing air and foam from oil', 'Removing air and foam from hydraulic oil – Triple R', 'Air bubbles cause cavitation, noise and faster oxidation. The Quicktoron removes up to 95% of the air from your oil. See how it works.',
      'Air and foam in oil cause cavitation, noise and faster oxidation. Air bubbles damage pumps and make hydraulic systems less precise. The Triple R Quicktoron is a cyclone de-aerator that removes up to 95% of the air bubbles from the oil and works independently of the filter element.'),
  fr=('Éliminer l\'air et la mousse de l\'huile', 'Air et mousse dans l\'huile hydraulique – Triple R', 'Les bulles d\'air provoquent cavitation, bruit et oxydation plus rapide. Le Quicktoron élimine jusqu\'à 95 % de l\'air de votre huile.',
      'L\'air et la mousse dans l\'huile provoquent cavitation, bruit et oxydation plus rapide. Les bulles d\'air endommagent les pompes et rendent les systèmes hydrauliques moins précis. Le Quicktoron de Triple R est un désaérateur à cyclone qui élimine jusqu\'à 95 % des bulles d\'air, indépendamment de l\'élément filtrant.')),
 'kb-bypass': dict(old='/tribology/bypass-oil-cleaning/', sec='opl', slug=('bypassfiltratie', 'bypass-filtration', 'filtration-en-derivation'),
  nl=('Bypassfiltratie (nevenstroomfiltratie) uitgelegd', 'Bypassfiltratie (nevenstroom) uitgelegd – Triple R', 'Hoe werkt een bypass- of nevenstroomfilter en waarom haalt het meer vuil uit olie dan een full-flowfilter? Heldere uitleg van Triple R.',
      'Bypassfiltratie, ook nevenstroomfiltratie genoemd, reinigt continu een kleine deelstroom van de olie naast het hoofdcircuit. Omdat die olie traag door 114 mm filtermedia stroomt, filtert een bypassfilter veel fijner dan een full-flowfilter en houdt het ook varnish en water vast. Het full-flowfilter gaat daardoor twee tot vijf keer langer mee.'),
  en=('Bypass filtration explained', 'Bypass oil filtration explained – Triple R', 'How does a bypass filter work and why does it remove more dirt from oil than a full-flow filter? A clear explanation from Triple R.',
      'Bypass filtration, also called offline or kidney-loop filtration, continuously cleans a small partial flow of the oil alongside the main circuit. Because that oil flows slowly through 114 mm of filter media, a bypass filter filters much more finely than a full-flow filter and also retains varnish and water.'),
  fr=('La filtration en dérivation expliquée', 'La filtration d\'huile en dérivation expliquée – Triple R', 'Comment fonctionne un filtre en dérivation et pourquoi retire-t-il plus de saletés qu\'un filtre à plein débit ? L\'explication claire de Triple R.',
      'La filtration en dérivation nettoie en continu un petit débit partiel de l\'huile, à côté du circuit principal. Comme cette huile traverse lentement 114 mm de média filtrant, un filtre en dérivation filtre bien plus finement qu\'un filtre à plein débit et retient aussi les vernis et l\'eau.')),
 'kb-schoon': dict(old='/tribology/guaranteed-clean/', sec='opl', slug=('gegarandeerd-schone-olie', 'guaranteed-clean-oil', 'huile-propre-garantie'),
  nl=('Gegarandeerd schone olie', 'Gegarandeerd schone olie met ISO 4406 – Triple R', 'Wat betekent schone olie in cijfers? Lees hoe Triple R reinheid meet volgens ISO 4406 en NAS 1638 en welke klasse uw machines nodig hebben.',
      'Schone olie is meetbaar. De reinheid wordt uitgedrukt in een ISO 4406-code of NAS 1638-klasse, die het aantal deeltjes per ml olie aangeeft. Triple R-filterelementen zijn Multipass-getest en filteren 1 tot 10 µm absoluut, zodat u de reinheidsklasse haalt die uw pompen, kleppen en lagers nodig hebben.'),
  en=('Guaranteed clean oil', 'Guaranteed clean oil to ISO 4406 – Triple R', 'What does clean oil mean in figures? See how Triple R measures cleanliness to ISO 4406 and NAS 1638 and which class your machines need.',
      'Clean oil can be measured. Cleanliness is expressed as an ISO 4406 code or NAS 1638 class, which indicates the number of particles per ml of oil. Triple R filter elements are Multipass tested and filter 1 to 10 µm absolute, so you reach the cleanliness class your pumps, valves and bearings need.'),
  fr=('Huile propre garantie', 'Huile propre garantie selon ISO 4406 – Triple R', 'Que signifie une huile propre en chiffres ? Voyez comment Triple R mesure la propreté selon ISO 4406 et NAS 1638 et quelle classe il vous faut.',
      'Une huile propre, cela se mesure. La propreté s\'exprime par un code ISO 4406 ou une classe NAS 1638, qui indique le nombre de particules par ml d\'huile. Les éléments filtrants Triple R sont testés Multipass et filtrent de 1 à 10 µm absolus, pour atteindre la classe requise par vos pompes, vannes et roulements.')),
 'kb-analyse': dict(old='/tribology/oil-analysis/', sec='opl', slug=('olieanalyse', 'oil-analysis', 'analyse-d-huile'),
  nl=('Olieanalyse: rapport lezen en oliestaal nemen', 'Olieanalyse: rapport lezen en oliestaal nemen – Triple R', 'Wat meet een olieanalyse en hoe leest u het rapport? Uitleg over ISO 4406, NAS 1638, water en TAN, plus hoe u correct een oliestaal neemt.',
      'Een olieanalyse meet hoe gezond uw olie en machine zijn: het aantal deeltjes volgens ISO 4406 en NAS 1638, het watergehalte, de viscositeit, het zuurgetal (TAN) en varnish. Zo ziet u slijtage en vervuiling voor er schade ontstaat. Triple R helpt u het rapport lezen en biedt een gratis analyse aan.'),
  en=('Oil analysis: reading the report and taking a sample', 'Oil analysis: reading the report, taking a sample – Triple R', 'What does an oil analysis measure and how do you read the report? ISO 4406, NAS 1638, water and TAN explained, plus how to take an oil sample.',
      'An oil analysis measures how healthy your oil and machine are: the particle count to ISO 4406 and NAS 1638, water content, viscosity, acid number (TAN) and varnish. It shows wear and contamination before damage occurs. Triple R helps you read the report and offers a free oil analysis.'),
  fr=('Analyse d\'huile : lire le rapport et prélever', 'Analyse d\'huile : rapport et prélèvement – Triple R', 'Que mesure une analyse d\'huile et comment lire le rapport ? ISO 4406, NAS 1638, eau et TAN expliqués, et comment prélever un échantillon.',
      'Une analyse d\'huile mesure la santé de votre huile et de votre machine : comptage de particules selon ISO 4406 et NAS 1638, teneur en eau, viscosité, indice d\'acide (TAN) et vernis. Elle révèle l\'usure et la contamination avant les dégâts. Triple R vous aide à lire le rapport et propose une analyse gratuite.')),
 'kb-beheer': dict(old='/total-oil-management/', sec='opl', slug=('totaal-oliebeheer', 'total-oil-management', 'gestion-totale-de-l-huile'),
  nl=('Totaal oliebeheer', 'Oliebeheer: meten, reinigen en opvolgen – Triple R', 'Een oliebeheerprogramma kost vaak minder dan olie verversen. Meten, reinigen en opvolgen voor minder stilstand en een langere olielevensduur.',
      'Totaal oliebeheer betekent dat u olie niet op vaste tijdstippen ververst, maar de toestand meet en de olie schoon houdt. Triple R combineert olieanalyse, bypassfiltratie en opvolging. Zo verlengt u de olielevensduur, voorkomt u ongeplande stilstand en verbruikt u minder olie dan bij periodiek verversen.'),
  en=('Total oil management', 'Oil management: measure, clean, monitor – Triple R', 'An oil management programme often costs less than changing oil. Measure, clean and monitor for less downtime and longer oil life.',
      'Total oil management means you no longer change oil at fixed intervals, but measure its condition and keep it clean. Triple R combines oil analysis, bypass filtration and follow-up. This extends oil life, prevents unplanned downtime and uses less oil than periodic oil changes.'),
  fr=('Gestion totale de l\'huile', 'Gestion de l\'huile : mesurer, nettoyer, suivre – Triple R', 'Un programme de gestion de l\'huile coûte souvent moins cher qu\'une vidange. Mesurer, nettoyer et suivre pour moins d\'arrêts et une huile durable.',
      'La gestion totale de l\'huile consiste à ne plus vidanger à intervalles fixes, mais à mesurer son état et à la garder propre. Triple R combine analyse d\'huile, filtration en dérivation et suivi. Vous prolongez la durée de vie de l\'huile, évitez les arrêts imprévus et consommez moins d\'huile.')),
 'kb-techniek': dict(old='/technology/', sec='opl', slug=('technologie', 'technology', 'technologie'),
  nl=('De technologie achter Triple R-filters', 'Technologie van het 114 mm dieptefilter – Triple R', 'Hoe een Triple R-filterelement werkt: 114 mm cellulose dieptefiltratie in drie stappen tegen deeltjes, varnish en water.',
      'Een Triple R-filterelement is een dieptefilter op basis van cellulose. De olie stroomt traag door 114 mm filtermedia in drie stappen: een grove laag, een niet-samengeperste laag en een samengeperste laag. Zo worden deeltjes, water en varnish in één element uit de olie gehaald, Multipass-getest tot 1 µm absoluut.'),
  en=('The technology behind Triple R filters', 'Technology of the 114 mm depth filter – Triple R', 'How a Triple R filter element works: 114 mm cellulose depth filtration in three stages against particles, varnish and water.',
      'A Triple R filter element is a cellulose-based depth filter. The oil flows slowly through 114 mm of filter media in three stages: a coarse layer, an uncompressed layer and a compressed layer. Particles, water and varnish are removed in one element, Multipass tested to 1 µm absolute.'),
  fr=('La technologie des filtres Triple R', 'Technologie du filtre en profondeur de 114 mm – Triple R', 'Comment fonctionne un élément filtrant Triple R : filtration en profondeur de 114 mm en cellulose, en trois étapes, contre particules, vernis et eau.',
      'Un élément filtrant Triple R est un filtre en profondeur à base de cellulose. L\'huile traverse lentement 114 mm de média en trois étapes : une couche grossière, une couche non comprimée et une couche comprimée. Particules, eau et vernis sont éliminés par un seul élément, testé Multipass jusqu\'à 1 µm absolu.')),
 'kb-rendement': dict(old='/profitability/', sec='opl', slug=('rentabiliteit', 'profitability', 'rentabilite'),
  nl=('De rentabiliteit van olie reinigen', 'Olie reinigen of verversen: rentabiliteit – Triple R', 'Olie reinigen is vaak goedkoper dan olie verversen. Bekijk wat u bespaart op olie, stilstand en onderhoud, en bereken het voor uw installatie.',
      'Olie reinigen is vaak goedkoper dan olie verversen: u betaalt filterelementen in plaats van nieuwe olie, afvoer en stilstand. Een element kost tussen € 25 en € 90 en volstaat voor tanks tot 1.000 liter. Met de besparingscalculator van Triple R rekent u uit wat dat voor uw installatie oplevert.'),
  en=('The profitability of cleaning oil', 'Cleaning or changing oil: profitability – Triple R', 'Cleaning oil is often cheaper than changing it. See what you save on oil, downtime and maintenance, and calculate it for your installation.',
      'Cleaning oil is often cheaper than changing it: you pay for filter elements instead of new oil, disposal and downtime. An element costs between € 25 and € 90 and is enough for tanks up to 1,000 litres. Use the Triple R savings calculator to work out what that means for your installation.'),
  fr=('La rentabilité du nettoyage de l\'huile', 'Nettoyer ou vidanger l\'huile : rentabilité – Triple R', 'Nettoyer l\'huile coûte souvent moins cher que la vidanger. Voyez vos économies d\'huile, d\'arrêts et de maintenance, et calculez-les.',
      'Nettoyer l\'huile coûte souvent moins cher que la vidanger : vous payez des éléments filtrants au lieu d\'huile neuve, d\'évacuation et d\'arrêts. Un élément coûte entre 25 € et 90 € et suffit pour des réservoirs jusqu\'à 1 000 litres. Le calculateur d\'économies Triple R chiffre le résultat pour votre installation.')),
 'kb-tribologie': dict(old='/tribology/', sec='opl', slug=('tribologie', 'tribology', 'tribologie'),
  nl=('Tribologie: waarom schone olie machines beschermt', 'Tribologie en olievervuiling uitgelegd – Triple R', 'Tribologie bestudeert wrijving, slijtage en smering. Lees hoe vervuiling in olie machines beschadigt en hoe u dat voorkomt.',
      'Tribologie is de wetenschap van wrijving, slijtage en smering. Olie vormt een film tussen bewegende onderdelen, en elke vervuiling tast die film aan. Vaste deeltjes, varnish, water en lucht veroorzaken samen de meeste machinestoringen. Triple R verwijdert die vervuiling en verlengt zo de levensduur van olie en machine.'),
  en=('Tribology: why clean oil protects machines', 'Tribology and oil contamination explained – Triple R', 'Tribology studies friction, wear and lubrication. See how oil contamination damages machines and how to prevent it.',
      'Tribology is the science of friction, wear and lubrication. Oil forms a film between moving parts, and any contamination attacks that film. Solid particles, varnish, water and air together cause most machine failures. Triple R removes this contamination and extends the life of both oil and machine.'),
  fr=('Tribologie : pourquoi une huile propre protège', 'Tribologie et contamination de l\'huile – Triple R', 'La tribologie étudie le frottement, l\'usure et la lubrification. Voyez comment la contamination de l\'huile abîme les machines et comment l\'éviter.',
      'La tribologie est la science du frottement, de l\'usure et de la lubrification. L\'huile forme un film entre les pièces mobiles, et toute contamination l\'attaque. Particules solides, vernis, eau et air causent ensemble la plupart des pannes. Triple R élimine cette contamination et prolonge la vie de l\'huile et de la machine.')),
}
def _sec(key, old, slugs, nl, en, fr):
    KB[key] = dict(old=old, sec='sec', slug=slugs, nl=nl, en=en, fr=fr)
_sec('s-hyd', '/application/hydraulic-systems/', ('hydraulische-systemen', 'hydraulic-systems', 'systemes-hydrauliques'), ('Oliefiltratie voor hydraulische systemen', 'Oliefiltratie voor hydraulische systemen – Triple R', 'Spuitgietmachines, persen en testbanken draaien langer met schone olie. Bypassfiltratie van Triple R voor hydraulische systemen.'), ('Oil filtration for hydraulic systems', 'Oil filtration for hydraulic systems – Triple R', 'Injection moulding machines, presses and test benches run longer on clean oil. Triple R bypass filtration for hydraulic systems.'), ('Filtration d\'huile pour systèmes hydrauliques', 'Filtration d\'huile pour systèmes hydrauliques – Triple R', 'Presses à injecter, presses et bancs d\'essai durent plus longtemps avec une huile propre. Filtration en dérivation Triple R pour l\'hydraulique.'))
_sec('s-marine', '/application/marine/', ('scheepvaart', 'marine', 'marine'), ('Oliefiltratie voor scheepvaart', 'Oliefiltratie voor scheepvaart en offshore – Triple R', 'Schone olie voor motoren, boegschroeven, kranen en lieren. Verwijder water en deeltjes aan boord, op verzoek met ATEX-certificering.'), ('Oil filtration for marine and offshore', 'Oil filtration for marine and offshore – Triple R', 'Clean oil for engines, thrusters, cranes and winches. Remove water and particles on board, with ATEX certification on request.'), ('Filtration d\'huile pour la marine', 'Filtration d\'huile pour la marine et l\'offshore – Triple R', 'Une huile propre pour moteurs, propulseurs, grues et treuils. Éliminez eau et particules à bord, avec certification ATEX sur demande.'))
_sec('s-wind', '/application/wind-energy/', ('windenergie', 'wind-energy', 'energie-eolienne'), ('Oliefiltratie voor windturbines', 'Tandwielkastolie reinigen in windturbines – Triple R', 'Houd de olie in tandwielkasten van windturbines schoon en droog en verleng de olielevensduur met bypassfiltratie.'), ('Oil filtration for wind turbines', 'Cleaning gearbox oil in wind turbines – Triple R', 'Keep the oil in wind turbine gearboxes clean and dry and extend its life with bypass filtration.'), ('Filtration d\'huile pour éoliennes', 'Nettoyer l\'huile des boîtes d\'éoliennes – Triple R', 'Gardez l\'huile des boîtes de vitesses d\'éoliennes propre et sèche et prolongez sa durée de vie grâce à la filtration en dérivation.'))
_sec('s-energie', '/application/energy/', ('energie', 'energy', 'energie'), ('Oliefiltratie voor de energiesector', 'Oliefiltratie voor energiecentrales en turbines – Triple R', 'Schone turbineolie en smeerolie voor energiecentrales. Triple R verwijdert varnish, water en deeltjes en beperkt ongeplande stilstand.'), ('Oil filtration for the energy sector', 'Oil filtration for power plants and turbines – Triple R', 'Clean turbine and lubricating oil for power plants. Triple R removes varnish, water and particles and limits unplanned downtime.'), ('Filtration d\'huile pour le secteur de l\'énergie', 'Filtration d\'huile pour centrales et turbines – Triple R', 'Huile de turbine et de lubrification propre pour les centrales. Triple R élimine vernis, eau et particules et limite les arrêts imprévus.'))
